import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as AlertDialog from "../alert-dialog";
import {
  shadcnAlertDialogContentSmClassName,
  shadcnAlertDialogFooterClassName,
  shadcnAlertDialogHeaderClassName,
  shadcnAlertDialogMediaClassName,
} from "./view";

export {
  actionsView,
  backdropView,
  closeView,
  descriptionView,
  popupView,
  portalView,
  rootView,
  titleView,
  triggerView,
  viewportView,
} from "../alert-dialog";
export type {
  AlertDialogStyle,
  CloseViewConfig,
  PartViewConfig,
  PortalViewConfig,
  RootViewConfig,
  TriggerViewConfig,
} from "../alert-dialog";

export {
  shadcnAlertDialogActionsClassName,
  shadcnAlertDialogBackdropClassName,
  shadcnAlertDialogCancelClassName,
  shadcnAlertDialogConfirmClassName,
  shadcnAlertDialogContentSmClassName,
  shadcnAlertDialogDescriptionClassName,
  shadcnAlertDialogFooterClassName,
  shadcnAlertDialogHeaderClassName,
  shadcnAlertDialogMediaClassName,
  shadcnAlertDialogPopupClassName,
  shadcnAlertDialogPortalClassName,
  shadcnAlertDialogRootClassName,
  shadcnAlertDialogTitleClassName,
  shadcnAlertDialogTriggerClassName,
  shadcnAlertDialogViewportClassName,
} from "./view";

export type AlertDialogContentSize = "default" | "sm";

export type ContentViewConfig = Readonly<{
  titleId: string;
  descriptionId: string;
  children: readonly Html[];
  size?: AlertDialogContentSize | undefined;
  className?: string | undefined;
  style?: AlertDialog.AlertDialogStyle | undefined;
}>;

const classNames = (...values: readonly (string | undefined)[]): string =>
  values
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const contentView = <ParentMessage>({
  titleId,
  descriptionId,
  children,
  size = "default",
  className,
  style,
}: ContentViewConfig): Html =>
  AlertDialog.popupView<ParentMessage>({
    titleId,
    descriptionId,
    children,
    className: classNames(
      size === "sm" ? shadcnAlertDialogContentSmClassName : undefined,
      className
    ),
    style,
  });

const divPartView = <ParentMessage>(
  baseClassName: string,
  { id, children, className, style }: AlertDialog.PartViewConfig
): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(id === undefined ? [] : [h.Id(id)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(baseClassName, className)),
    ],
    children
  );
};

export const headerView = <ParentMessage>(
  config: AlertDialog.PartViewConfig
): Html => divPartView<ParentMessage>(shadcnAlertDialogHeaderClassName, config);

export const footerView = <ParentMessage>(
  config: AlertDialog.PartViewConfig
): Html => divPartView<ParentMessage>(shadcnAlertDialogFooterClassName, config);

export const mediaView = <ParentMessage>(
  config: AlertDialog.PartViewConfig
): Html => divPartView<ParentMessage>(shadcnAlertDialogMediaClassName, config);

export {
  alertDialogActionsClassName as shadcnAlertDialogActionsClassName,
  alertDialogBackdropClassName as shadcnAlertDialogBackdropClassName,
  alertDialogCancelClassName as shadcnAlertDialogCancelClassName,
  alertDialogConfirmClassName as shadcnAlertDialogConfirmClassName,
  alertDialogDescriptionClassName as shadcnAlertDialogDescriptionClassName,
  alertDialogPopupClassName as shadcnAlertDialogPopupClassName,
  alertDialogPortalClassName as shadcnAlertDialogPortalClassName,
  alertDialogRootClassName as shadcnAlertDialogRootClassName,
  alertDialogTitleClassName as shadcnAlertDialogTitleClassName,
  alertDialogTriggerClassName as shadcnAlertDialogTriggerClassName,
  alertDialogViewportClassName as shadcnAlertDialogViewportClassName,
} from "../alert-dialog/view";

export const shadcnAlertDialogContentSmClassName = "max-w-xs";

export const shadcnAlertDialogHeaderClassName =
  "grid gap-2 text-center sm:text-left";

export const shadcnAlertDialogFooterClassName =
  "flex flex-col-reverse gap-2 sm:flex-row sm:justify-end";

export const shadcnAlertDialogMediaClassName =
  "mx-auto flex size-10 items-center justify-center rounded-full bg-gray-100 text-gray-950 sm:mx-0";

import { describe, expect, test } from "vitest";

import * as AlertDialog from "./index";

describe("shadcn AlertDialog registry view", () => {
  test("reuses the Foldkit AlertDialog view contract", () => {
    expect(AlertDialog.rootView).toBeTypeOf("function");
    expect(AlertDialog.contentView).toBeTypeOf("function");
    expect(AlertDialog.headerView).toBeTypeOf("function");
    expect(AlertDialog.footerView).toBeTypeOf("function");
    expect(AlertDialog.mediaView).toBeTypeOf("function");
    expect(AlertDialog.closeView).toBeTypeOf("function");
    expect(AlertDialog.shadcnAlertDialogPopupClassName).toContain("rounded");
    expect(AlertDialog.shadcnAlertDialogContentSmClassName).toContain(
      "max-w-xs"
    );
  });
});
